use codegraph_ui_server::{serve,Options};
use std::{io::{Read,Write},net::TcpStream,sync::{Arc,atomic::{AtomicBool,Ordering},mpsc},time::Duration};
fn request(port:u16,target:&str,host:&str,extra:&str,method:&str,body:&str)->String{let mut stream=TcpStream::connect(("127.0.0.1",port)).unwrap();stream.set_read_timeout(Some(Duration::from_secs(5))).unwrap();write!(stream,"{method} {target} HTTP/1.1\r\nHost: {host}\r\nConnection: close\r\nContent-Length: {}\r\n{extra}\r\n{body}",body.len()).unwrap();let mut response=String::new();stream.read_to_string(&mut response).unwrap();response}
#[test]fn loopback_server_serves_assets_and_enforces_origin_method_and_path_boundaries(){let dir=tempfile::tempdir().unwrap();let root=dir.path().join("project");std::fs::create_dir(&root).unwrap();std::fs::write(root.join("app.ts"),"export function start(){return 1;}\n").unwrap();let cg=codegraph_core::CodeGraph::init_and_index(root.to_str().unwrap(),None).unwrap();cg.close();let viewer=dir.path().join("viewer");std::fs::create_dir(&viewer).unwrap();std::fs::write(viewer.join("index.html"),"<main>native viewer</main>").unwrap();std::fs::write(viewer.join("module.wasm"),"wasm fixture").unwrap();let options=Options{root:root.to_string_lossy().into_owned(),viewer,port:0,port_fallback:false,read_only:true};let stop=Arc::new(AtomicBool::new(false));let signal=stop.clone();let(sender,receiver)=mpsc::channel();let server=std::thread::spawn(move||serve(options,&signal,|port|sender.send(port).unwrap()).map_err(|e|e.to_string()));let port=receiver.recv_timeout(Duration::from_secs(5)).unwrap();let host=format!("127.0.0.1:{port}");
    let index=request(port,"/",&host,"","GET","");assert!(index.contains("200 OK"));assert!(index.contains("native viewer"));let stats=request(port,"/api/stats",&host,"","GET","");assert!(stats.contains("200 OK"));assert!(stats.contains("rusqlite"));let wasm=request(port,"/module.wasm",&host,"","GET","");assert!(wasm.contains("application/wasm"));assert!(request(port,"/api/stats","evil.example","","GET","").contains("403"));assert!(request(port,"/api/stats",&host,"Origin: https://evil.example\r\n","GET","").contains("403"));assert!(request(port,"/%2e%2e/secret",&host,"","GET","").contains("403"));assert!(request(port,"/api/trails",&host,"Content-Type: application/json\r\nx-codegraph-ui: 1\r\n","POST","{}").contains("403"));assert!(request(port,"/api/stats",&host,"","OPTIONS","").contains("405"));stop.store(true,Ordering::Relaxed);server.join().unwrap().unwrap();}
